// Runs once for all items.
// Normalises the form submission and builds the exact Anthropic API request body.
// Edit SERVICES / AVAILABILITY here — nowhere else — if your prices or hours change.

const SERVICES_AND_PRICES = [
  'Standard clean — $120',
  'Deep clean — $220',
  'Move-out clean — $280',
];

const AVAILABILITY = [
  'Weekday evenings, 6:00 pm to 9:00 pm',
  'Weekends, anytime 7:00 am to 10:00 pm',
];

const SYSTEM_PROMPT = [
  "You are writing a reply on behalf of Jane, who runs a home cleaning service. You answer new leads in Jane's voice: warm, plain-spoken, human. No marketing fluff, no stacked exclamation marks, no corporate filler.",
  '',
  'THE ONLY FACTS YOU MAY USE',
  'Services and prices (USD):',
  SERVICES_AND_PRICES.map(function (s) { return '- ' + s; }).join('\n'),
  'Availability:',
  AVAILABILITY.map(function (s) { return '- ' + s; }).join('\n'),
  '',
  'HARD RULES',
  '1. Never state a price, service, add-on, discount, duration, or availability window that is not listed above. If the lead asks about something outside that list (recurring plans, supplies, per-square-foot pricing, a date you cannot confirm), say plainly that Jane will confirm it. Do not guess, estimate, or extrapolate. Inventing a number is the worst thing you can do here.',
  '2. Keep the reply body under 120 words. Count the words before you answer.',
  '3. Greet the lead by first name only.',
  "4. Reflect the specific thing they asked for using their own words — reuse or quote a short phrase from their message so it is obvious a person read it. Do not flatten it into generic language like 'your cleaning needs'.",
  '5. Answer only what the facts above can answer. Leave the rest to Jane rather than filling the gap.',
  '6. Propose exactly one concrete next step, offering exactly two time options, both inside the availability above (for example a weekday evening slot and a weekend slot). Offer them as choices and ask which suits — never present a slot as already booked or confirmed.',
  '7. Sign off as Jane. The final line of the reply must be exactly: — Jane',
  '8. VAGUE MESSAGES: if you cannot tell which service they want or what they actually need, do NOT guess and do NOT propose times. Write a short warm reply that asks exactly ONE clarifying question, and sign off as Jane. Set is_vague to true.',
  '',
  'OUTPUT FORMAT',
  'Return one JSON object and nothing else — no prose, no code fences. Keys:',
  '- "asked_for": a short factual phrase (12 words max) describing what the lead asked for, in their terms. Used for internal logging.',
  '- "is_vague": true or false',
  '- "subject": email subject line, 8 words max, no emoji',
  '- "reply": the plain-text email body, with line breaks, ending with the line — Jane',
].join('\n');

const DAY_NAMES = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

// Renders in the n8n instance's timezone, e.g. "Mon 17 Aug 2026, 3:02pm".
function readableDate(iso) {
  const d = new Date(iso);
  if (isNaN(d.getTime())) return String(iso || '');
  const h24 = d.getHours();
  const h12 = h24 % 12 === 0 ? 12 : h24 % 12;
  const mins = String(d.getMinutes()).padStart(2, '0');
  return DAY_NAMES[d.getDay()] + ' ' + d.getDate() + ' ' + MONTH_NAMES[d.getMonth()] + ' ' + d.getFullYear() + ', ' + h12 + ':' + mins + (h24 < 12 ? 'am' : 'pm');
}

const items = $input.all();
const out = [];

for (const item of items) {
  const src = item.json || {};

  // The Form Trigger returns one key per field label.
  const name = String(src.Name || src.name || '').trim();
  const email = String(src.Email || src.email || '').trim();
  const message = String(src.Message || src.message || '').trim();

  if (!email) throw new Error('Lead submitted with no email address — cannot reply. Name given: ' + (name || '(blank)'));
  if (!message) throw new Error('Lead submitted with no message — nothing to reply to. Email: ' + email);

  const firstName = (name.split(/\s+/)[0] || 'there').replace(/[^\p{L}\p{M}'-]/gu, '') || 'there';
  const submittedAt = src.submittedAt || new Date().toISOString();

  const userMessage = [
    'New lead from the website form.',
    '',
    'Name: ' + (name || '(not given)'),
    'First name to greet: ' + firstName,
    'Email: ' + email,
    'Submitted at: ' + submittedAt,
    '',
    'Their message, verbatim:',
    '"""',
    message,
    '"""',
  ].join('\n');

  out.push({
    json: {
      name: name,
      first_name: firstName,
      email: email,
      message: message,
      submitted_at: submittedAt,
      submitted_at_readable: readableDate(submittedAt),
      claudeRequest: {
        model: 'claude-sonnet-5',
        max_tokens: 700,
        temperature: 0.6,
        system: SYSTEM_PROMPT,
        messages: [
          { role: 'user', content: userMessage },
          // Prefill forces the model straight into the JSON object.
          { role: 'assistant', content: '{' },
        ],
      },
    },
  });
}

return out;

// Turns the Anthropic response into { subject, reply, asked_for, ... }
const resp = $input.first().json || {};
const lead = $('Normalize Lead').first().json || {};

const text = (resp.content && resp.content[0] && resp.content[0].text) || '';

if (resp.stop_reason === 'max_tokens') {
  throw new Error('Claude hit the max_tokens limit and the reply was cut off, for ' + (lead.email || 'unknown lead') + '. Raise max_tokens in the Normalize Lead node.');
}

// The assistant turn was prefilled with "{", so the response continues from
// inside the object. Try the likely shapes in order and take the first that parses.
const cleaned = text
  .replace(/^\s*```(?:json)?\s*/i, '')
  .replace(/\s*```\s*$/, '')
  .trim();

const candidates = [];
const firstBrace = cleaned.indexOf('{');
const lastBrace = cleaned.lastIndexOf('}');
// The model ignored the prefill and emitted a whole object of its own.
if (firstBrace !== -1 && lastBrace > firstBrace) candidates.push(cleaned.slice(firstBrace, lastBrace + 1));
// The expected case: a continuation of the prefilled "{".
candidates.push('{' + cleaned);
// Same, but with anything trailing the final "}" discarded.
if (lastBrace !== -1) candidates.push('{' + cleaned.slice(0, lastBrace + 1));
candidates.push('{' + text);

let parsed = null;
for (const candidate of candidates) {
  try {
    const attempt = JSON.parse(candidate);
    if (attempt && typeof attempt === 'object') { parsed = attempt; break; }
  } catch (e) { /* try the next shape */ }
}

if (!parsed) {
  throw new Error('Claude returned no parsable JSON for ' + (lead.email || 'unknown lead') + '. Raw response: ' + text.slice(0, 400));
}

let reply = String(parsed.reply == null ? '' : parsed.reply).trim();
if (!reply) {
  throw new Error('Claude returned an empty reply body for ' + (lead.email || 'unknown lead'));
}

// Safety net: the sign-off is a hard requirement, so guarantee it.
if (!/—\s*Jane\s*$/.test(reply) && !/\bJane\s*$/.test(reply)) {
  reply = reply + '\n\n— Jane';
}

const wordCount = reply.split(/\s+/).filter(Boolean).length;

return [{
  json: {
    name: lead.name,
    first_name: lead.first_name,
    email: lead.email,
    message: lead.message,
    submitted_at: lead.submitted_at,
    submitted_at_readable: lead.submitted_at_readable,
    subject: String(parsed.subject || 'Thanks for getting in touch').trim(),
    reply: reply,
    asked_for: String(parsed.asked_for || '(not captured)').trim(),
    is_vague: parsed.is_vague === true,
    word_count: wordCount,
    over_word_limit: wordCount >= 120,
    stop_reason: resp.stop_reason || null,
  },
}];

// Reached from any failed step. Builds one human-readable alert per failure.
function safeNode(nodeName) {
  try { return $(nodeName).first().json || {}; } catch (e) { return {}; }
}

const lead = safeNode('Normalize Lead');
const drafted = safeNode('Parse Claude Reply');

const out = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const step = j.failed_step || 'Unknown step';

  let errText;
  const err = j.error;
  if (typeof err === 'string') {
    errText = err;
  } else if (err && (err.message || err.description)) {
    errText = [err.message, err.description].filter(Boolean).join(' — ');
  } else if (err) {
    errText = JSON.stringify(err).slice(0, 800);
  } else {
    errText = '(no error detail returned by n8n)';
  }

  const leadName = lead.name || j.Name || j.name || '(unknown)';
  const leadEmail = lead.email || j.Email || j.email || '(unknown)';
  const leadMessage = lead.message || j.Message || j.message || '(unavailable)';

  const body = [
    'A lead did not make it all the way through the workflow.',
    '',
    'WHAT BROKE',
    'Step: ' + step,
    'Error: ' + errText,
    '',
    'WHICH LEAD',
    'Name: ' + leadName,
    'Email: ' + leadEmail,
    'Submitted: ' + (lead.submitted_at_readable || lead.submitted_at || '(unknown)'),
    'Their message:',
    leadMessage,
    '',
    'REPLY DRAFTED BY CLAUDE',
    drafted.reply ? drafted.reply : '(no reply was drafted before the failure)',
    '',
    'WAS IT SENT?',
    // Sheets logging is the only step that runs after the send succeeds.
    step.indexOf('Google Sheets') === 0
      ? 'Yes — the reply was sent. Only the spreadsheet row failed.'
      : 'No — the reply was NOT sent. Follow up by hand.',
    '',
    'Execution: ' + $execution.id,
  ].join('\n');

  out.push({
    json: {
      failed_step: step,
      error_text: errText,
      lead_name: leadName,
      lead_email: leadEmail,
      lead_message: leadMessage,
      submitted_at: lead.submitted_at || '',
      sheet_request: drafted.asked_for || '(not captured — failed before Claude replied)',
      drafted_reply: drafted.reply || '',
      alert_subject: 'Lead workflow failed at ' + step + ' — ' + leadEmail,
      alert_body: body,
      sheet_reply_note: 'NOT SENT — workflow failed at ' + step + ' (' + errText.slice(0, 180) + ')',
    },
  });
}

return out;
